document.addEventListener("DOMContentLoaded",()=>{const e={facts:[["Location","Bharatpur, Rajasthan","Lohagarh Fort is the famous Iron Fort of Bharatpur."],["Known for","Defensive strength","The issue highlights its remarkable defensive design that withstood numerous attacks."],["Builder","Maharaja Suraj Mal","The fort is strongly associated with Jat ruler Maharaja Suraj Mal of Bharatpur."],["Meaning","Iron Fort","Lohagarh means Iron Fort, reflecting strength rather than just metal construction."],["Architecture","Mud ramparts + stone gates","Its defence relied on thick earthen ramparts, moats, strong gates and resilient planning."],["Explorer focus","Battles + defence","This page explains history, builder, architecture, defensive features, battles, facts and gallery."]],history:[["Bharatpur power centre","Lohagarh Fort represents the strength of the Bharatpur kingdom and Jat resistance in Rajasthan."],["Maharaja Suraj Mal era","The fort is associated with Maharaja Suraj Mal, one of the most important rulers of Bharatpur."],["Resilience story","Unlike many decorative forts, Lohagarh is famous mainly for its ability to absorb attacks and survive sieges."],["Heritage today","Today it is remembered as a practical military fort and an important chapter in Rajasthan regional history."]],builders:[["Maharaja Suraj Mal","Credited with building and strengthening Lohagarh Fort as a defensive centre of Bharatpur."],["Jat military planning","The fort reflects practical regional defence strategy rather than only royal ornamentation."],["Bharatpur rulers","Successive Bharatpur rulers maintained the fort as a symbol of independence and strength."],["Fort engineers and workers","Local builders shaped ramparts, moats, gates and walls designed to resist repeated attacks."]],architecture:[["Thick earthen ramparts","Mud and earthen ramparts helped absorb cannon impact better than brittle decorative surfaces."],["Moat system","Water-filled defensive barriers made direct assaults more difficult."],["Strong gateways","Massive gates controlled entry and made attacking movement slower and more dangerous."],["Functional layout","The architecture focuses on survival, defence, storage, movement and command."]],defence:[["Shock-absorbing walls","Thick mud ramparts could absorb artillery impact, helping the fort survive bombardment."],["Layered defence","Walls, moats, gates and internal positioning worked together instead of relying on one feature."],["Difficult siege target","The fort design made it hard for attackers to quickly breach or control."],["Iron reputation","Its nickname reflects toughness, endurance and unbroken resistance."]],battles:[["Repeated attacks","The issue notes that Lohagarh Fort withstood numerous attacks, making battle resilience a core section."],["Bharatpur sieges","The fort is best discussed through its siege history and ability to frustrate powerful enemies."],["Defensive success","Its fame comes from not falling easily, showing the value of practical engineering."],["Legacy of resistance","Battle stories turned Lohagarh into a symbol of regional pride and military endurance."]],points:[["gate","Main gateway",48,64,"Entry defence","Strong gates controlled entry and slowed attacking forces."],["rampart","Earthen ramparts",38,47,"Defensive wall","Thick ramparts helped absorb artillery impact and protect the fort interior."],["moat","Moat belt",61,52,"Water defence","The moat made direct assault and movement toward walls difficult."],["battle","Battle memory point",70,38,"Siege history","Represents attacks and sieges that shaped Lohagarh reputation."],["court","Inner command area",50,48,"Fort interior","Internal spaces supported movement, planning, storage and defence."],["heritage","Heritage learning stop",30,68,"Visitor learning","Explains builder, architecture, battles and responsible heritage behaviour."]],gallery:[["Defensive fort walls","../../assets/heritage_forts.png","Visual placeholder for Lohagarh strong defensive identity."],["Bharatpur heritage","../../assets/heritage_monuments.png","Fort remains and gateways communicate regional history."],["Rajasthan fort story","../../assets/hero_banner.png","Lohagarh is presented as a heritage learning explorer."],["Architecture details","../../assets/heritage_temples.png","Stone and structural details help explain fort architecture."]],interesting:[["Iron Fort identity","Lohagarh means Iron Fort, a name tied to toughness and resilience."],["Practical defence","Its fame comes from military performance more than decorative luxury."],["Mud can be strategic","Thick earthen ramparts could perform better against cannon fire than expected."],["Heritage responsibility","Visitors should avoid damaging walls, littering or climbing fragile sections."]],faqs:[["What is Lohagarh Fort famous for?","It is famous for its strong defensive design and ability to withstand repeated attacks."],["Who built Lohagarh Fort?","It is associated with Maharaja Suraj Mal of Bharatpur."],["Why is it called the Iron Fort?","The name reflects its reputation for toughness, endurance and strong defence."],["What makes its architecture different?","Its thick mud ramparts, moats and functional planning made it highly defensive."],["What does this explorer cover?","History, builder, architecture, defensive features, battles, facts, gallery and landing integration."]]},a=e=>String(e).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;"),t=e=>document.getElementById(e);function r(e,t,r){return`<article class="${t}"><span>0${r+1}</span><h3>${a(e[0])}</h3><p>${a(e[1])}</p></article>`}function n(r){const n=e.points.find(e=>e[0]===r)||e.points[0];document.querySelectorAll(".map-pin").forEach(e=>e.classList.toggle("active",e.dataset.point===n[0])),t("map-info").innerHTML=`<span>${a(n[4])}</span><h3>${a(n[1])}</h3><p>${a(n[5])}</p>`}t("facts-grid").innerHTML=e.facts.map(e=>`<article class="fact-card"><span>${a(e[0])}</span><strong>${a(e[1])}</strong><p>${a(e[2])}</p></article>`).join(""),t("history-grid").innerHTML=e.history.map((e,a)=>r(e,"history-card",a)).join(""),t("builder-grid").innerHTML=e.builders.map((e,a)=>r(e,"builder-card",a)).join(""),t("architecture-grid").innerHTML=e.architecture.map((e,a)=>r(e,"architecture-card",a)).join(""),t("defence-grid").innerHTML=e.defence.map((e,a)=>r(e,"defence-card",a)).join(""),t("battles-grid").innerHTML=e.battles.map((e,a)=>r(e,"battle-card",a)).join(""),t("interesting-grid").innerHTML=e.interesting.map((e,a)=>r(e,"interesting-card",a)).join(""),t("faq-list").innerHTML=e.faqs.map(e=>`<details class="faq-item"><summary>${a(e[0])}</summary><p>${a(e[1])}</p></details>`).join(""),t("map-pins").innerHTML=e.points.map((e,t)=>`<button class="map-pin" type="button" data-point="${a(e[0])}" style="left:${e[2]}%;top:${e[3]}%" aria-label="${a(e[1])}">${t+1}</button>`).join(""),document.querySelectorAll(".map-pin").forEach(e=>e.addEventListener("click",()=>n(e.dataset.point))),t("gallery-grid").innerHTML=e.gallery.map(e=>`<article class="gallery-card"><img src="${a(e[1])}" alt="${a(e[0])}" onerror="this.src='../../assets/hero_banner.png'"><div><h3>${a(e[0])}</h3><p>${a(e[2])}</p></div></article>`).join(""),n(e.points[0][0]),window.LohagarhFortExplorer={facts:()=>[...e.facts],points:()=>[...e.points],faqs:()=>[...e.faqs]}});